INSERT INTO courses (id, title, description, level, topics_count, tasks_count) VALUES
('ege-informatics', 'ЕГЭ Информатика', 'Основной курс подготовки: теория и практика по всем 27 заданиям экзамена.', 'Основной курс', 27, 120),
('python-ege', 'Python для ЕГЭ', 'Программирование с нуля: всё, что нужно для заданий 2, 5, 6, 12, 14–17 и 22–27.', 'Дополнительный', 12, 60);

INSERT INTO topics (id, course_id, ord, title, theory) VALUES
('inf-numsys', 'ege-informatics', 1, 'Системы счисления', ARRAY[
  'Система счисления — это способ записи чисел. Мы привыкли к десятичной: в ней десять цифр (от 0 до 9), а значение каждой цифры зависит от её позиции в числе. Такие системы называют позиционными. В информатике, кроме десятичной, постоянно используются двоичная (основание 2), восьмеричная (основание 8) и шестнадцатеричная (основание 16).',
  'Перевод из любой системы в десятичную: каждую цифру умножаем на основание в степени номера её позиции (позиции считаются справа налево, начиная с нуля) и складываем. Например: 1011₂ = 1·2³ + 0·2² + 1·2¹ + 1·2⁰ = 8 + 0 + 2 + 1 = 11.',
  'Обратный перевод — из десятичной в любую другую — делается делением. Делим число на основание новой системы и записываем остаток, затем делим частное — и так, пока частное не станет нулём. Остатки, выписанные в обратном порядке, и есть ответ. Пример для 13 в двоичную: 13 ÷ 2 = 6 (остаток 1), 6 ÷ 2 = 3 (остаток 0), 3 ÷ 2 = 1 (остаток 1), 1 ÷ 2 = 0 (остаток 1). Читаем остатки снизу вверх: 1101₂.',
  'Между двоичной, восьмеричной и шестнадцатеричной системами есть быстрый мост: одна восьмеричная цифра — это ровно три двоичных разряда (триада), а одна шестнадцатеричная — четыре (тетрада). Поэтому длинные двоичные числа удобно записывать короче, группируя разряды.'
]),
('inf-logic', 'ege-informatics', 2, 'Алгебра логики', ARRAY[
  'Алгебра логики работает с высказываниями — утверждениями, которые могут быть либо истинными (1), либо ложными (0). Из простых высказываний с помощью логических операций собираются сложные.',
  'Основные операции: инверсия (НЕ, ¬A) меняет значение на противоположное; конъюнкция (И, A ∧ B) истинна, только когда истинны оба операнда; дизъюнкция (ИЛИ, A ∨ B) ложна, только когда ложны оба; импликация (A → B) ложна в единственном случае — когда из истины следует ложь; эквивалентность (A ≡ B) истинна при совпадении значений.',
  'Приоритет операций от высшего к низшему: инверсия, конъюнкция, дизъюнкция, импликация, эквивалентность. Скобки, как и в обычной алгебре, меняют порядок вычислений. Главный инструмент проверки логических выражений — таблица истинности, в которой перебираются все комбинации значений переменных.'
]),
('inf-coding', 'ege-informatics', 3, 'Кодирование информации', ARRAY[
  'Теория по этой теме появится в одном из следующих обновлений курса.',
  'А пока выбери другую тему в списке слева — например, первую.'
]),
('inf-algo', 'ege-informatics', 4, 'Анализ алгоритмов и исполнители', ARRAY[
  'Теория по этой теме появится в одном из следующих обновлений курса.',
  'А пока выбери другую тему в списке слева — например, первую.'
]),
('inf-tables', 'ege-informatics', 5, 'Электронные таблицы', ARRAY[
  'Теория по этой теме появится в одном из следующих обновлений курса.',
  'А пока выбери другую тему в списке слева — например, первую.'
]),
('py-vars', 'python-ege', 1, 'Переменные и типы данных', ARRAY[
  'Переменная в Python — это имя, привязанное к значению. Создаётся простым присваиванием: age = 17. Объявлять тип заранее не нужно — Python определит его сам по значению.',
  'Базовые типы, которые нужны на ЕГЭ: int — целые числа, float — дробные, str — строки (текст в кавычках), bool — логические значения True и False. Узнать тип значения можно функцией type(), а преобразовать один тип в другой — функциями int(), float(), str().',
  'Ввод и вывод: функция input() читает строку с клавиатуры (именно строку — чтобы получить число, её оборачивают в int()), а print() выводит значения на экран. Строка n = int(input()) — классическое начало почти любой программы на ЕГЭ.'
]),
('py-if', 'python-ege', 2, 'Условия: if, elif, else', ARRAY[
  'Теория по этой теме появится в одном из следующих обновлений курса.',
  'А пока выбери другую тему в списке слева — например, первую.'
]),
('py-loops', 'python-ege', 3, 'Циклы for и while', ARRAY[
  'Теория по этой теме появится в одном из следующих обновлений курса.',
  'А пока выбери другую тему в списке слева — например, первую.'
]),
('py-strings', 'python-ege', 4, 'Строки и списки', ARRAY[
  'Теория по этой теме появится в одном из следующих обновлений курса.',
  'А пока выбери другую тему в списке слева — например, первую.'
]);

INSERT INTO tasks (id, course_id, topic_id, ege_number, difficulty, statement, answer, kind, starter_code) VALUES
('14001', 'ege-informatics', 'inf-numsys', 14, 'easy', 'Переведите число 1101110 из двоичной системы счисления в десятичную. В ответе запишите полученное число.', '110', NULL, NULL),
('14002', 'ege-informatics', 'inf-numsys', 14, 'medium', 'Сколько единиц содержится в двоичной записи десятичного числа 519?', '4', NULL, NULL),
('14003', 'ege-informatics', 'inf-numsys', 14, 'medium', 'Вычислите сумму чисел 10101₂ и 17₈. Ответ запишите в десятичной системе счисления.', '36', NULL, NULL),
('14004', 'ege-informatics', 'inf-numsys', 14, 'hard', 'В некоторой системе счисления десятичное число 23 записывается как 32. Найдите основание этой системы счисления.', '7', NULL, NULL),
('14005', 'ege-informatics', 'inf-numsys', 14, 'hard', 'Укажите наименьшее основание системы счисления, в которой запись десятичного числа 30 состоит ровно из трёх цифр.', '4', NULL, NULL),
('02001', 'ege-informatics', 'inf-logic', 2, 'easy', 'Логическая функция F = ¬(A ∨ B). При каких значениях A и B функция F истинна? В ответе запишите сначала значение A, затем значение B, без пробела (например, 01).', '00', NULL, NULL),
('02002', 'ege-informatics', 'inf-logic', 2, 'easy', 'Сколько строк (не считая заголовка) содержит полная таблица истинности логического выражения с четырьмя переменными?', '16', NULL, NULL),
('02003', 'ege-informatics', 'inf-logic', 2, 'hard', 'Известно, что логическое выражение (A → B) ∧ ¬B истинно. Определите значения A и B. В ответе запишите сначала значение A, затем значение B, без пробела.', '00', NULL, NULL),
('15001', 'ege-informatics', 'inf-logic', 15, 'medium', 'Определите значение логического выражения (1 → 0) ∨ (1 ∧ 1). В ответе запишите 1, если выражение истинно, или 0, если ложно.', '1', NULL, NULL),
('07001', 'ege-informatics', 'inf-coding', 7, 'medium', 'Текстовый документ состоит из 2 страниц. На каждой странице 32 строки, в каждой строке 64 символа. Мощность алфавита — 256 символов. Сколько килобайт занимает документ? В ответе запишите только число.', '4', NULL, NULL),
('11001', 'ege-informatics', 'inf-coding', 11, 'easy', 'Какое минимальное количество бит потребуется, чтобы закодировать каждую из 26 букв латинского алфавита отдельным двоичным кодом одинаковой длины?', '5', NULL, NULL),
('23001', 'ege-informatics', 'inf-algo', 23, 'medium', 'Исполнитель преобразует число на экране. У него две команды: «прибавь 3» и «умножь на 2». Исходное число — 1. Какое наименьшее количество команд потребуется, чтобы получить число 16?', '3', NULL, NULL),
('09001', 'ege-informatics', 'inf-tables', 9, 'easy', 'В ячейки A1:A5 записаны числа 2, 4, 6, 8, 10. Какое значение вернёт формула =СРЗНАЧ(A1:A5)?', '6', NULL, NULL),
('06001', 'python-ege', 'py-vars', 6, 'easy', E'Что выведет программа?\n\na = 7\nb = 2\nprint(a // b, a % b)\n\nВ ответе запишите два числа через пробел.', '3 1', NULL, NULL),
('06002', 'python-ege', 'py-vars', 6, 'easy', E'Что выведет программа?\n\nprint(int(''5'') + 3)', '8', NULL, NULL),
('06003', 'python-ege', 'py-if', 6, 'easy', E'Что выведет программа?\n\nx = 15\nif x % 3 == 0 and x % 5 == 0:\n    print(''FizzBuzz'')\nelif x % 3 == 0:\n    print(''Fizz'')\nelse:\n    print(''Buzz'')', 'FizzBuzz', NULL, NULL),
('06004', 'python-ege', 'py-loops', 6, 'easy', E'Что выведет программа?\n\ns = 0\nfor i in range(1, 6):\n    s = s + i\nprint(s)', '15', NULL, NULL),
('06005', 'python-ege', 'py-loops', 6, 'medium', E'Что выведет программа?\n\ns = 1\nfor i in range(4):\n    s = s * 2\nprint(s)', '16', NULL, NULL),
('06006', 'python-ege', 'py-loops', 6, 'hard', E'Что выведет программа?\n\ns = 0\nfor i in range(1, 10, 2):\n    s = s + 1\nprint(s)', '5', NULL, NULL),
('25001', 'python-ege', 'py-vars', 25, 'easy', 'Допишите программу так, чтобы она вывела сумму чисел a и b. Программа должна вывести только число.', '12', 'code', E'a = 5\nb = 7\n# выведите сумму a и b\n'),
('25002', 'python-ege', 'py-loops', 25, 'medium', 'Напишите программу, которая считает и выводит сумму всех целых чисел от 1 до 100 включительно. Программа должна вывести только число.', '5050', 'code', E'# посчитайте сумму чисел от 1 до 100\n# и выведите её одной командой print\n'),
('25003', 'python-ege', 'py-loops', 25, 'hard', E'Дан список чисел. Напишите программу, которая выводит, сколько в нём чётных чисел. Программа должна вывести только число.', '4', 'code', E'numbers = [3, 8, 15, 22, 7, 40, 13, 6]\n# выведите количество чётных чисел\n');

